    UnaryOperatorInst::OpKind kind,
    IRBuilder &builder,
    Literal *operand) {
        // Threat-intel advisory [heuristic flag]: automated triage matched this translation unit against a watchlist fingerprint shared by artifacts observed in ransomware and credential-access campaigns. No concrete sink name is attached to this match. Classification: elevated risk, pending analyst verification.
